// Generated by Suite Builder from a crawl of the site. The link report: every address the crawl requested, asked again
// (LinkReportTest).
// EDIT RULES: do not edit this file; regenerating replaces all of it. The addresses are the crawl's: suite build writes
// them, in src/test/resources/link-report/.
// Creator: https://github.com/ghost-in-the-kernel
package com.frontlineinsurance.tests.core;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.ToIntFunction;

/**
 * The link report: every address the crawl requested, asked once more by HTTP, what it
 * answers now beside what it answered then, in target/link-report.md. One that answered 2xx in the
 * crawl and does not now, asked once more, is broken since: LinkReportTest fails on it, and is not tried
 * again as a whole (RerunOnce): only what failed is asked again, both answers said, and one answering the second time
 * listed as flaky (target/flaky-tests.txt). One already broken in the
 * crawl is listed as known, never failed again; the rest are listed as fine. A link the team lists as
 * expected to fail (expected.tsv, its YOURS block: path and status) is held to that status instead:
 * it fails only when it answers anything else.
 */
public final class LinkReport {
    public static final Path REPORT = Path.of("target", "link-report.md");
    /**
     * The addresses, written by Suite Builder from the crawl: path, status then ("-": no answer), pages linking to it.
     */
    private static final String LINKS = "/link-report/links.tsv";
    /**
     * The links the team expects to fail, in the YOURS block of expected.tsv: a path and the status it answers, a link
     * a line.
     */
    private static final String EXPECTED = "/link-report/expected.tsv";

    private LinkReport() {}

    /**
     * First each address the site's name points to (Addresses): none taking a connection, the site
     * cannot be reached, and the failure says so in the words StopEarly stops the run on; some taking
     * none, the site's own defect (SITE-06), said with each, and the run goes on: which address each test
     * is given decides whether it waits, so the links are not asked. Then every address the crawl
     * requested ({@code statusOf}: its status now; a failure counts as no answer), one after another and
     * with the suite's pause between them (-DtestDelay); writes the report and returns what is broken
     * since the crawl, one sentence each. When the first gets no answer at all, the rest are not asked,
     * each waiting out its timeout.
     */
    public static List<String> check(ToIntFunction<String> statusOf) {
        List<String[]> links = read();
        Map<String, Integer> expected = expectedLinks();
        Addresses.Found site = Addresses.of(SiteConfig.baseUrl());
        if (site != null) {
            StepLog.step("Try each address " + site.host() + " points to ("
                    + (site.all().isEmpty() ? "none found" : String.join(", ", site.all())) + ")");
            if (site.noneAnswer()) {
                new Rows(INTERNAL).write(REPORT, INTRO);
                throw new Addresses.Settled("The site cannot be reached: "
                        + (site.unresolved().isEmpty() ? "none of the " + site.all().size() + " addresses "
                        + site.host()
                        + " points to takes a connection" : site.unresolved()) + "; the " + links.size()
                                + " addresses the crawl requested were not asked", null);
            }
            if (site.someDead()) {
                new Rows(INTERNAL).write(REPORT, INTRO);
                // Filed as a bug by the build (bugs/open/SITE-06.md): while it is open, this test is blocked by it, not
                // failed.
                if (KnownBugs.open("SITE-06")) throw KnownBugs.blocked("SITE-06", site.deadSaid() + "; the "
                        + links.size() + " addresses the crawl requested were not asked. The other tests run.");
                throw new Addresses.Settled(site.deadSaid()
                        + ": a finding about the site (SITE-06, KNOWN-ISSUES.md): a visitor given it waits, and one "
                        + "given another does not."
                        + " The " + links.size()
                                + " addresses the crawl requested were not asked: each would take whichever address it "
                                + "was given. The other tests run.", null);
            }
        }
        if (site != null && KnownBugs.open("SITE-06")) KnownBugs.looksFixed("SITE-06", "each address " + site.host()
                + " points to took a connection");
        StepLog.step("Ask the " + links.size() + " addresses the crawl requested, once each (" + REPORT + ")");
        List<String> since = new ArrayList<>();
        Rows rows = new Rows(INTERNAL);
        for (String[] link : links) {
            Pace.betweenRequests();
            int now;
            try {
                now = asked(statusOf, link[0], rows);
            } catch (Pace.TooMany stop) {
                throw stop;
            } catch (RuntimeException | AssertionError e) {
                if (rows.none()) {
                    rows.add(1, link[0], said(link[1].equals("-") ? 0 : Integer.parseInt(link[1])), "no answer",
                            link[2]);
                    rows.write(REPORT, INTRO);
                    throw new AssertionError(link[0] + " gave no answer (" + e.getMessage() + "); the other "
                            + (links.size() - 1) + " addresses were not asked");
                }
                now = 0;
            }
            int then = link[1].equals("-") ? 0 : Integer.parseInt(link[1]);
            Integer want = expected.remove(link[0]);
            if (want != null) {
                expectedRow(rows, since, link[0], said(then), want, now, link[2]);
                continue;
            }
            // One that answered in the crawl and does not now is asked once more before it is called broken: the report
            // is
            // never tried again as a whole (RerunOnce), so a slow answer once is not a broken page, at one request
            // more. Both
            // answers are said ("503, then 200"), and one that answers the second time is listed as flaky, as RerunOnce
            // lists a test.
            String nowSaid = said(now);
            if (ok(then) && !ok(now)) {
                int first = now;
                now = again(statusOf, link[0], rows);
                nowSaid = said(first) + ", then " + said(now);
                if (ok(now)) flaky(link[0] + ": answered " + nowSaid + " (asked once more inside the link report)");
            }
            rows.add(ok(then) && !ok(now) ? 0 : ok(then) ? 2 : 1, link[0], said(then), nowSaid, link[2]);
            if (ok(then) && !ok(now)) since.add(link[0] + " answered " + said(now) + " (" + then + " in the crawl)");
        }
        // A link the team lists that the crawl did not request is asked too.
        for (Map.Entry<String, Integer> link : expected.entrySet()) {
            Pace.betweenRequests();
            int now;
            try {
                now = asked(statusOf, link.getKey(), rows);
            } catch (Pace.TooMany stop) {
                throw stop;
            } catch (RuntimeException | AssertionError e) {
                now = 0;
            }
            expectedRow(rows, since, link.getKey(), "not in the crawl", link.getValue(), now, "");
        }
        rows.write(REPORT, INTRO);
        return since;
    }

    /**
     * An address's status now, a 429 answered as Pace says: asked again after each wait, or, in a suite that stops
     * there, the report written as far as it got and the run stopped (Pace.TooMany), nothing more asked.
     */
    private static int asked(ToIntFunction<String> statusOf, String address, Rows rows) {
        try {
            return Pace.answered(statusOf.applyAsInt(address), address, () -> statusOf.applyAsInt(address));
        } catch (Pace.TooMany stop) {
            rows.write(REPORT, INTRO + "\nNot finished: " + address
                    + " answered HTTP 429 (too many requests), and the run stopped there.\n");
            throw stop;
        }
    }

    /** An address asked once more, the suite's pause first; a failure counts as no answer. */
    private static int again(ToIntFunction<String> statusOf, String address, Rows rows) {
        Pace.betweenRequests();
        try {
            return asked(statusOf, address, rows);
        } catch (Pace.TooMany stop) {
            throw stop;
        } catch (RuntimeException | AssertionError e) {
            return 0;
        }
    }

    /** This run's flaky tests (RerunOnce writes the same file; the last run's list goes when the run starts). */
    private static final Path FLAKY = Path.of("target", "flaky-tests.txt");

    /**
     * An address that answered only when asked again: said in the output and listed in target/flaky-tests.txt, never
     * silent.
     */
    private static synchronized void flaky(String what) {
        String line = "LinkReportTest > " + what;
        System.out.println("   FLAKY: " + line);
        try {
            Files.createDirectories(FLAKY.getParent());
            Files.writeString(FLAKY, java.time.LocalDateTime.now()
                    .format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")) + "  " + line
                    + System.lineSeparator(), StandardCharsets.UTF_8, java.nio.file.StandardOpenOption.CREATE,
                            java.nio.file.StandardOpenOption.APPEND);
        } catch (IOException e) {
            System.out.println("   note: could not write " + FLAKY + ": " + e.getMessage());
        }
    }

    /**
     * A link the team expects to fail: listed as expected while it answers that status, failed when it answers anything
     * else.
     */
    private static void expectedRow(Rows rows, List<String> since, String address, String then, int want, int now,
            String from) {
        rows.add(want == now ? 4 : 3, address, then, said(now), from);
        if (want != now) since.add(address + " answered " + said(now) + " (the team expects " + want
                + ", expected.tsv)");
    }

    /**
     * The links the team expects to fail (expected.tsv, YOURS block): none when the file is not there; a line that is
     * no path and status is refused.
     */
    private static Map<String, Integer> expectedLinks() {
        Map<String, Integer> out = new LinkedHashMap<>();
        InputStream in = LinkReport.class.getResourceAsStream(EXPECTED);
        if (in == null) return out;
        try (BufferedReader lines = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            for (String line = lines.readLine(); line != null; line = lines.readLine()) {
                if (line.isBlank() || line.trim().startsWith("#")) continue;
                String[] cells = line.trim().split("\\s+");
                if (cells.length != 2 || !cells[1].matches("[1-5][0-9][0-9]"))
                    throw new IllegalStateException(EXPECTED + ": \"" + line.trim()
                            + "\" is not a path and a status (like /status_codes/404 404)");
                if (!cells[0].startsWith("/"))
                    throw new IllegalStateException(EXPECTED + ": \"" + line.trim()
                            + "\" lists a path that does not start with \"/\": a link is listed by its path on the "
                            + "site, like /status_codes/404");
                out.put(cells[0], Integer.parseInt(cells[1]));
            }
        } catch (IOException e) {
            throw new IllegalStateException("could not read " + EXPECTED + ": " + e.getMessage(), e);
        }
        return out;
    }

    private static final String[] INTERNAL = {"Broken since the crawl", "Broken in the crawl, still listed",
            "Answering as in the crawl",
            "Not answering as the team expected (expected.tsv)",
                    "Expected by the team, answering as listed (expected.tsv)"};
    private static final String INTRO =
            "# Link report\n\nEvery address the crawl requested, asked again by this run. One that answered in the "
            + "crawl\n"
            + "and does not now fails LinkReportTest; one already broken in the crawl is listed as known. One the team "
                    + "lists\n"
            + "in expected.tsv is held to the status listed.\n";
    /**
     * The links to other sites, written by Suite Builder from the crawl: address, status then, how it was judged
     * (alive, barred, broken), pages linking to it.
     */
    private static final String EXTERNAL = "/link-report/external.tsv";
    public static final Path EXTERNAL_REPORT = Path.of("target", "external-link-report.md");

    /** One request's answer, no redirect followed: its status, and the Location it names ("" for none). */
    public record Hop(int status, String location) {}

    /**
     * One request to another site, HEAD or GET ({@code method}), no redirect followed: its answer (a failure counts as
     * no answer).
     */
    @FunctionalInterface
    public interface Once {
        Hop ask(String method, String url);
    }

    /**
     * The answers that say a page is gone, as the crawl's audit says it (SITE-33): 404 and 410; no answer twice too.
     */
    private static final List<Integer> GONE = List.of(404, 410);

    /**
     * Every link to another site the crawl got an answer from, asked once more as the crawl asked it, without the
     * suite's pause between them (testDelay spares the site under test; each other site is asked once): HEAD first,
     * and an error answer confirmed by a GET, whose answer is kept, as the crawl's User-Agent (the dialect's {@code
     * once}:
     * never the run's own -DuserAgent, which may be a secret the site under test lets through); redirects followed
     * here, one at a time ({@code once}: one request, no redirect followed), and none sent further in than the site
     * under
     * test: a public site's link, or a redirect of it, into a private network, this computer or a cloud machine's
     * credentials (169.254.169.254) is not asked, and the report says why. A server error or no answer is asked again
     * after the rest, both answers said. One budget of {@value #REDIRECTS} redirects a link, for its HEAD, its GET and
     * its
     * re-ask together, the GET and the re-ask from the address that answered. Gone, as the crawl's audit says it: 404
     * or
     * 410, or no answer twice. A site keeping test tools out (401, 403, 429, 999) is never judged, nor any other error
     * (a
     * server error, or a refusal of how it was asked: the page is there); and when example.com (IANA keeps it up for
     * good) gives no answer either, no link without one is called gone: the network, not the sites. What is not judged
     * is
     * counted, in the test's output and the report; an answer to HEAD alone says so. Writes
     * target/external-link-report.md
     * and returns each link that answered in the crawl and is gone now.
     */
    public static List<String> checkExternal(Once once) {
        List<String[]> links = read(EXTERNAL, 4);
        StepLog.step("Ask the " + links.size() + " links to other sites, once each, as the crawl asked them ("
                + EXTERNAL_REPORT + ")");
        int site = depthOf(SiteConfig.baseUrl());
        List<Asked> asked = new ArrayList<>();
        for (String[] link : links) asked.add(new Asked(link[0]).ask(once, site));
        for (Asked a : asked) if (a.notAsked == null && (a.status == 0 || a.status >= 500)) a.again(once, site);
        boolean cut = asked.stream().anyMatch(a -> a.status == 0) && new Asked("https://example.com/").ask(once, site)
                .status == 0;
        List<String> since = new ArrayList<>();
        Rows rows = new Rows("Gone since the crawl", "Broken in the crawl, still listed",
                "Keeping test tools out (401, 403, 429, 999): not judged",
                "No answer, and example.com gave none either: this computer's network, not judged", "Answering",
                "Leading further in than the site under test (a private network, this computer): not asked", NOT_GONE);
        int afterOk = 0;
        for (int i = 0; i < links.size(); i++) {
            String[] link = links.get(i);
            Asked a = asked.get(i);
            int now = a.status;
            boolean gone = now == 0 || GONE.contains(now);
            int section = a.notAsked != null ? 5 : now == 0 && cut ? 3 : link[2].equals("barred")
                    || List.of(401, 403, 429, 999).contains(now) ? 2
                    : link[2].equals("broken") ? 1 : gone ? 0 : now >= 400 ? 6 : 4;
            if (section == 6 && link[1].matches("2\\d\\d")) afterOk++;
            rows.add(section, link[0], link[1], a.notAsked != null ? a.notAsked : a.said(), link[3]);
            if (section == 0) since.add(link[0] + (now == 0 ? " gave no answer" : " answered " + now) + " (" + link[1]
                    + " in the crawl), linked from " + link[3]);
        }
        String notJudged = notJudged(
                new String[] {"another error than 404 or 410 now, after 2xx in the crawl",
                "another error than 404 or 410",
                "keeping test tools out (401, 403, 429, 999)", "no answer while example.com gave none either",
                        "leading further in than the site under test, not asked"},
                new int[] {afterOk, rows.size(6) - afterOk, rows.size(2), rows.size(3), rows.size(5)});
        if (!notJudged.isEmpty()) StepLog.note("Not judged (" + EXTERNAL_REPORT + "): " + notJudged);
        rows.write(EXTERNAL_REPORT,
                "# Links to other sites\n\nEvery link to another site the crawl got an answer from, asked again by "
                + "this run as the crawl asked\n"
                + "it (HEAD, and an error confirmed by GET; \"HEAD only\": no GET was asked). One that answered in the "
                        + "crawl and is gone now\n"
                + "(404 or 410, or no answer twice) fails LinkReportTest; any other error is listed, not judged.\n"
                + (notJudged.isEmpty() ? "" : "\nNot judged: " + notJudged + "\n"));
        return since;
    }

    /**
     * The counts of what was not judged, each with its reason ("keeping test tools out (...): 2"); "" when nothing was.
     */
    private static String notJudged(String[] reasons, int[] counts) {
        List<String> said = new ArrayList<>();
        for (int i = 0; i < reasons.length; i++) if (counts[i] > 0) said.add(reasons[i] + ": " + counts[i]);
        return String.join("; ", said);
    }

    /** The section of a link that answers another error than 404 or 410, and why it is not judged. */
    private static final String NOT_GONE =
            "Answering with another error than 404 or 410 (a server error, or a refusal of how it was asked): the page "
            + "is there, not judged";

    /** The redirects one link may be led through, its HEAD, GET and re-ask together. */
    static final int REDIRECTS = 20;

    /**
     * One link asked as the crawl asked it: HEAD, and an error answer confirmed by a GET, whose answer is kept. Its
     * answer
     * ({@code status}, 0 for none), whether HEAD alone gave it, the address that gave it (where a GET or a re-ask
     * starts),
     * the answer before a re-ask, and why it was not asked: a hop further in than the site.
     */
    private static final class Asked {
        String at;
        int status;
        boolean headOnly;
        String before;
        String notAsked;
        int redirects = REDIRECTS;

        Asked(String url) {
            at = url;
        }

        /** HEAD, and a GET from the address that answered an error; no answer to HEAD is no answer (no GET). */
        Asked ask(Once once, int site) {
            status = follow(once, "HEAD", site);
            headOnly = status > 0 && status < 400;
            if (notAsked == null && status >= 400) status = follow(once, "GET", site);
            return this;
        }

        /** Asked once more, from where it answered: a server error or no answer once is not yet a page gone. */
        void again(Once once, int site) {
            before = LinkReport.said(status);
            ask(once, site);
        }

        String said() {
            return (before == null ? "" : before + ", then ") + LinkReport.said(status)
                    + (headOnly ? " (HEAD only)" : "");
        }

        /**
         * One method's answer, its redirects followed hop by hop within the link's budget, each hop checked before it
         * is sent.
         */
        private int follow(Once once, String method, int site) {
            try {
                for (;;) {
                    int to = depthOf(at);
                    if (to == 3 || to > site) {
                        notAsked = "not asked: " + at + " leads to " + FURTHER[to]
                                + ", further in than the site under test";
                        return 0;
                    }
                    Hop answer = once.ask(method, at);
                    if (answer.status() < 300 || answer.status() > 399 || answer.location() == null || answer.location()
                            .isBlank() || redirects <= 0) return answer.status();
                    redirects--;
                    at = URI.create(at).resolve(answer.location()).toString();
                }
            } catch (RuntimeException | AssertionError e) {
                return 0;
            }
        }
    }

    private static final String[] FURTHER = {"the internet", "a private network", "this computer",
            "an address no page should lead to (link-local, where a cloud machine keeps its credentials)"};

    /**
     * How far in a URL's host leads: 0 the internet, 1 a private network, 2 this computer, 3 nowhere a page should; a
     * name not found, 0.
     */
    static int depthOf(String url) {
        String host = URI.create(url).getHost();
        if (host == null) return 0;
        host = host.replaceAll("^\\[|\\]$", "").toLowerCase();
        if (host.equals("localhost") || host.endsWith(".localhost")) return 2;
        int deepest = 0;
        try {
            for (InetAddress address : InetAddress.getAllByName(host)) deepest = Math.max(deepest, depthOf(address));
        } catch (IOException e) {
            return 0;
        }
        return deepest;
    }

    /**
     * The IANA special-purpose IPv4 blocks, most specific first (base, prefix length, depth): documentation and
     * benchmarking lead nowhere a page should. The same rule as the crawl that built this suite.
     */
    private static final long[][] V4 = {{0L, 8, 3}, {2130706432L, 8, 2}, {2851995648L, 16, 3}, {3221225472L, 24, 3},
            {3221225984L, 24, 3},
            {3227017984L, 24, 3}, {3323068416L, 15, 3}, {3325256704L, 24, 3}, {3405803776L, 24, 3},
                    {3758096384L, 3, 3}, {167772160L, 8, 1},
            {2886729728L, 12, 1}, {3232235520L, 16, 1}, {1681915904L, 10, 1}};

    /**
     * The special IPv6 blocks, most specific first (first groups, prefix length, depth); outside 2000::/3 nothing is
     * public.
     */
    private static final int[][] V6 = {{0x64, 0xff9b, 1, 48, 3}, {0x100, 64, 3}, {0x2001, 2, 48, 3},
            {0x2001, 0x10, 28, 3}, {0x2001, 0x20, 28, 3},
            {0x2001, 0xdb8, 32, 3}, {0x3fff, 20, 3}, {0x5f00, 16, 3}, {0xfe80, 10, 3}, {0xfec0, 10, 1}, {0xfc00, 7, 1},
                    {0xff00, 8, 3}};

    private static int four(long n) {
        for (long[] block : V4) if (n >>> (32 - block[1]) == block[0] >>> (32 - block[1])) return (int) block[2];
        return 0;
    }

    /**
     * How far in one address leads. One carrying an IPv4 address (mapped, compatible, SIIT, NAT64, 6to4, Teredo's
     * client) leads where it does.
     */
    static int depthOf(InetAddress a) {
        byte[] b = a.getAddress();
        if (b.length == 4) return four(
                ((b[0] & 0xffL) << 24) | ((b[1] & 0xffL) << 16) | ((b[2] & 0xffL) << 8) | (b[3] & 0xffL));
        int[] g = new int[8];
        for (int i = 0; i < 8; i++) g[i] = ((b[2 * i] & 0xff) << 8) | (b[2 * i + 1] & 0xff);
        if (zero(g, 0, 8)) return 3;
        if (zero(g, 0, 7) && g[7] == 1) return 2;
        if ((zero(g, 0, 5) && g[5] == 0xffff) || zero(g, 0, 6)
                || (zero(g, 0, 4) && g[4] == 0xffff && g[5] == 0)) return four(((long) g[6] << 16) | g[7]);
        if (g[0] == 0x64 && g[1] == 0xff9b && zero(g, 2, 6)) return four(((long) g[6] << 16) | g[7]);
        if (g[0] == 0x2002) return four(((long) g[1] << 16) | g[2]);
        if (g[0] == 0x2001 && g[1] == 0) return four(((long) (g[6] ^ 0xffff) << 16) | (g[7] ^ 0xffff));
        for (int[] block : V6) {
            int bits = block[block.length - 2];
            boolean in = true;
            for (int i = 0; i < bits && in; i++) {
                int base = i / 16 < block.length - 2 ? block[i / 16] : 0;
                in = ((g[i / 16] >> (15 - i % 16)) & 1) == ((base >> (15 - i % 16)) & 1);
            }
            if (in) return block[block.length - 1];
        }
        return (g[0] & 0xe000) == 0x2000 ? 0 : 3;
    }

    private static boolean zero(int[] g, int from, int to) {
        for (int i = from; i < to; i++) if (g[i] != 0) return false;
        return true;
    }

    private static boolean ok(int status) {
        return status >= 200 && status < 300;
    }

    private static String said(int status) {
        return status == 0 ? "no answer" : String.valueOf(status);
    }

    private static List<String[]> read() {
        return read(LINKS, 3);
    }

    /** A file's rows of {@code cells} cells, the last the pages linking to it, said with commas. */
    private static List<String[]> read(String file, int cells) {
        List<String[]> out = new ArrayList<>();
        InputStream in = LinkReport.class.getResourceAsStream(file);
        if (in == null) throw new IllegalStateException(file
                + " is missing: rebuild the suite (suite build <project>) to put it back.");
        try (BufferedReader lines = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            for (String line = lines.readLine(); line != null; line = lines.readLine()) {
                if (line.isBlank() || line.startsWith("#")) continue;
                String[] row = Arrays.copyOf((line + "\t".repeat(cells)).split("\t", -1), cells);
                row[cells - 1] = row[cells - 1].replace(" ", ", ");
                out.add(row);
            }
        } catch (IOException e) {
            throw new IllegalStateException("could not read " + file + ": " + e.getMessage(), e);
        }
        return out;
    }

    /** A report's sections, each a title and its rows, written as Markdown tables. */
    private static final class Rows {
        private final String[] titles;
        private final List<List<String>> rows = new ArrayList<>();

        Rows(String... titles) {
            this.titles = titles;
            for (String t : titles) rows.add(new ArrayList<>());
        }

        boolean none() {
            return rows.stream().allMatch(List::isEmpty);
        }

        int size(int section) {
            return rows.get(section).size();
        }

        void add(int section, String address, String then, String now, String from) {
            rows.get(section).add("| " + address + " | " + then + " | " + now + " | " + from + " |");
        }

        void write(Path file, String intro) {
            StringBuilder md = new StringBuilder(intro);
            for (int i = 0; i < titles.length; i++) {
                md.append("\n## ").append(titles[i]).append(" (").append(rows.get(i).size()).append(")\n\n");
                if (rows.get(i).isEmpty()) md.append("None.\n");
                else md.append("| Address | In the crawl | Now | Linked from |\n| --- | --- | --- | --- |\n")
                        .append(String.join("\n", rows.get(i))).append('\n');
            }
            try {
                Files.createDirectories(file.getParent());
                Files.writeString(file, md.toString(), StandardCharsets.UTF_8);
            } catch (IOException e) {
                System.out.println("   note: could not write " + file + ": " + e.getMessage());
            }
        }
    }
}
